/*
 * Source-count compatibility: two supplied banks are incomplete:
 * High Court = 99 actual question blocks; Secretariat = 118 actual question blocks.
 * Sync their UI totals to the supplied data so mock2.html does not reject the bank.
 */
window.addEventListener("load", function(){
  try {
    if (typeof categories !== "undefined" && Array.isArray(categories)) {
      Object.keys(mock2DemoQuestionBanks).forEach(function(name){
        var row = categories.find(function(c){ return c[1] === name; });
        if (row) row[3] = mock2DemoQuestionBanks[name].length;
      });
    }
  } catch (e) { console.warn("Demo bank count sync skipped:", e); }
});
